#include <ATen/ops/from_blob.h>
#include <c10/core/ScalarType.h>
#include <c10/cuda/CUDAFunctions.h>
#include <cuda.h>
#include <cuda_runtime.h>

#include <pybind11/pybind11.h>
#include <pybind11/pytypes.h>
#include <pybind11/stl.h>

#include <torch/python.h>
#include <torch/types.h>

#include <cstdio>
#include <cstring>
#include <numeric>
#include <optional>
#include <stdexcept>
#include <vector>

#include "exception.h"
#include "ts_ext_ops.h"

namespace py = pybind11;

static size_t numel_of(const std::vector<int64_t> &shape) {
  return std::accumulate(shape.begin(), shape.end(), size_t{1},
                         [](size_t a, int64_t b) {
                           if (b < 0)
                             throw std::runtime_error("Negative dim");
                           return a * (size_t)b;
                         });
}

static size_t dtype_nbytes(c10::ScalarType dtype) {
  return (size_t)at::elementSize(dtype);
}

torch::Tensor create_tensor(const std::vector<int64_t> &shape,
                            c10::ScalarType dtype) {
  auto current_device = c10::cuda::current_device();
  auto options =
      at::TensorOptions(at::kCUDA).dtype(dtype).device_index(current_device);

  const size_t bytes = dtype_nbytes(dtype) * numel_of(shape);

  CUDA_CHECK(cudaDeviceSynchronize());
  void *ptr = nullptr;
  CUDA_CHECK(cudaMalloc(&ptr, bytes));

  return at::from_blob(
      ptr, shape,
      [](void *p) {
        cudaError_t cerr = cudaFree(p);
        if (cerr != cudaSuccess) {
          std::fprintf(stderr, "cudaFree failed in deleter: %s\n",
                       cudaGetErrorString(cerr));
        }
      },
      options);
}

py::bytearray create_ipc_handle(void *ptr) {
  cudaIpcMemHandle_t handle{};
  CUDA_CHECK(cudaIpcGetMemHandle(&handle, ptr));
  return py::bytearray(reinterpret_cast<const char *>(handle.reserved),
                       CUDA_IPC_HANDLE_SIZE);
}

void sync_ipc_handles(
    int rank, const std::vector<int> &device_ids, void **buffer_ptrs_gpu,
    const std::vector<std::optional<py::bytearray>> &all_gathered_handles,
    const std::optional<py::bytearray> & /*root_unique_id_opt*/) {

  const int num = (int)device_ids.size();
  const int rdma_rank = 0;

  TS_HOST_ASSERT((size_t)num == all_gathered_handles.size());

  std::vector<cudaIpcMemHandle_t> ipc_handles(num);
  std::vector<void *> buffer_ptrs(num, nullptr);

  for (int i = 0, offset = rdma_rank * num; i < num; ++i) {
    TS_HOST_ASSERT(all_gathered_handles[offset + i].has_value());
    std::string s = (std::string)all_gathered_handles[offset + i].value();
    TS_HOST_ASSERT(s.size() == CUDA_IPC_HANDLE_SIZE);
    if (offset + i != rank) {
      std::memcpy(ipc_handles[i].reserved, s.data(), CUDA_IPC_HANDLE_SIZE);
      CUDA_CHECK(cudaIpcOpenMemHandle(&buffer_ptrs[i], ipc_handles[i],
                                      cudaIpcMemLazyEnablePeerAccess));
    }
  }

  CUDA_CHECK(cudaMemcpy(buffer_ptrs_gpu, buffer_ptrs.data(),
                        sizeof(void *) * buffer_ptrs.size(),
                        cudaMemcpyHostToDevice));
  CUDA_CHECK(cudaDeviceSynchronize());
}

"""The profiler and convert to torch utils"""

from __future__ import annotations
from enum import Enum
import torch
from tvm import tir
import numpy as np
from tilelang.utils.target import parse_device
from tilelang.utils.allocator import BaseAllocator


def is_float8_dtype(dtype: torch.dtype) -> bool:
    return dtype in {
        torch.float8_e5m2,
        torch.float8_e5m2fnuz,
        torch.float8_e4m3fn,
        torch.float8_e4m3fnuz,
    }


def fp8_remove_negative_zeros_(tensor: torch.Tensor):
    assert is_float8_dtype(tensor.dtype), "Input tensor must be of float8 dtype"
    bits = tensor.view(torch.uint8)
    zeros_mask = tensor == 0
    bits[zeros_mask] = 0x00


class TensorSupplyType(Enum):
    Integer = 1
    Uniform = 2
    Normal = 3
    Randn = 4
    Zero = 5
    One = 6
    Auto = 7


def tensor(
    shape: tuple[int, ...],
    dtype: torch.dtype,
    device: str | torch.device | int | None = None,
    allocator: BaseAllocator | None = None,
    return_peers: bool | None = None,
) -> torch.Tensor | list[torch.Tensor]:
    """Allocate a tensor using the given allocator or standard torch allocation.

    Args:
        shape: The shape of the tensor to allocate.
        dtype: The data type of the tensor.
        device: The device to allocate on (if not using allocator).
        allocator: Optional BaseAllocator for distributed memory allocation.
        return_peers: If True, return peer tensors for distributed allocation.

    Returns:
        A torch.Tensor or list of torch.Tensors (if return_peers is True).
    """
    if allocator is not None:
        assert allocator.initialized(), "Allocator is not initialized"
        if device is not None:
            device = parse_device(device)
            assert allocator.device == device, (
                f"Allocator device must be the same as the device of the tensor, but got {allocator.device} != {device}"
            )
        return allocator._allocate_tensor(shape, dtype, return_peers)
    else:
        return torch.empty(shape, dtype=dtype, device=device)


def map_torch_type(intype) -> torch.dtype:
    # Convert to string if needed
    if not isinstance(intype, str):
        intype = str(intype)

    if intype == "float8_e4m3":
        assert hasattr(torch, "float8_e4m3fn"), "torch.float8_e4m3fn is not supported in this version of torchPlease upgrade torch >= 2.1.0"
        return torch.float8_e4m3fn
    elif intype == "float8_e5m2":
        assert hasattr(torch, "float8_e5m2"), "torch.float8_e5m2 is not supported in this version of torchPlease upgrade torch >= 2.1.0"
        return torch.float8_e5m2
    elif intype == "e4m3fnuz_float8":
        assert hasattr(torch, "float8_e4m3fnuz"), (
            "torch.float8_e4m3fnuz is not supported in this version of torchPlease upgrade torch >= 2.2.0"
        )
        return torch.float8_e4m3fnuz
    elif intype == "float8_e8m0fnu":
        assert hasattr(torch, "float8_e8m0fnu"), (
            "torch.float8_e8m0fnu is not supported in this version of torchPlease upgrade torch >= 2.8.0"
        )
        return torch.float8_e8m0fnu
    elif intype == "float4_e2m1fnx2":
        assert hasattr(torch, "float4_e2m1fnx2"), (
            "torch.float4_e2m1fnx2 is not supported in this version of torchPlease upgrade torch >= 2.8.0"
        )
        return torch.float4_e2m1fnx2
    elif "float4" in intype:
        # PyTorch doesn't support float4, use int8 as storage type
        return torch.int8
    else:
        return getattr(torch, intype)


def get_tensor_supply(supply_type: TensorSupplyType = TensorSupplyType.Integer):
    from tilelang.engine.param import KernelParam
    from .device import get_current_device

    def get_tensor(param: KernelParam) -> torch.Tensor:
        # Convert tvm.DataType to torch.dtype for tensor creation
        dtype: torch.dtype = param.torch_dtype()
        device = get_current_device()

        if hasattr(param, "shape") and not param.shape:
            raise ValueError(
                f"TensorType must have a shape, but got {type(param)}, "
                "likely you are trying to generate a random tensor with a dynamic symbolic shape."
            )

        # Check if with dynamic symbolic shape
        for shape in param.shape:
            if isinstance(shape, tir.Var):
                raise ValueError(
                    f"TensorType must have a static shape, but got {shape}, "
                    "likely you are trying to generate a random tensor with a dynamic symbolic shape."
                )

        shape = list(map(int, param.shape))
        if supply_type == TensorSupplyType.Auto:
            is_unsigned = param.is_unsigned()
            is_float8 = param.is_float8()
            is_float4 = param.is_float4()
            is_boolean = param.is_boolean()
            if is_unsigned:
                return torch.randint(low=0, high=3, size=shape, device=device, dtype=dtype)
            elif is_float8:
                return torch.randint(low=-128, high=128, size=shape, device=device, dtype=torch.int8).to(dtype)
            elif is_float4:
                return torch.randint(low=0, high=16, size=shape, device=device, dtype=dtype)
            elif is_boolean:
                return torch.randint(low=0, high=2, size=shape, device=device, dtype=dtype)
            elif dtype in {torch.float16, torch.float32, torch.bfloat16}:
                return torch.empty(*shape, device=device, dtype=dtype).uniform_(-1.0, 1.0)
            else:
                return torch.randint(low=-2, high=3, size=shape, device=device, dtype=dtype)

        if dtype == torch.int8 and supply_type in [
            TensorSupplyType.Uniform,
            TensorSupplyType.Normal,
        ]:
            return torch.ones(*shape, device=device, dtype=dtype)

        if supply_type == TensorSupplyType.Integer:
            is_unsigned = param.is_unsigned()
            is_float8 = param.is_float8()
            is_float4 = param.is_float4()
            is_boolean = param.is_boolean()
            if is_unsigned:
                return torch.randint(low=0, high=3, size=shape, device=device, dtype=dtype)
            elif is_float8:
                return torch.randint(low=-128, high=128, size=shape, device=device, dtype=torch.int8).to(dtype)
            elif is_float4:
                return torch.randint(low=0, high=16, size=shape, device=device, dtype=dtype)
            elif is_boolean:
                return torch.randint(low=0, high=2, size=shape, device=device, dtype=dtype)
            else:
                return torch.randint(low=-2, high=3, size=shape, device=device, dtype=dtype)
        elif supply_type == TensorSupplyType.Uniform:
            return torch.empty(*shape, device=device, dtype=torch.float32).uniform_(-1.0, 1.0).to(dtype)
        elif supply_type == TensorSupplyType.Normal:
            return torch.empty(*shape, device=device, dtype=torch.float32).normal_(-1.0, 1.0).to(dtype)
        elif supply_type == TensorSupplyType.Randn:
            return torch.randn(*shape, device=device).to(dtype)
        elif supply_type == TensorSupplyType.Zero:
            return torch.zeros(*shape, device=device, dtype=dtype)
        elif supply_type == TensorSupplyType.One:
            return torch.ones(*shape, device=device, dtype=dtype)
        else:
            raise NotImplementedError(supply_type)

    return get_tensor


# Adapted from https://github.com/pytorch/pytorch/blob/main/torch/testing/_comparison.py
def _compare_attributes(
    actual: torch.Tensor,
    expected: torch.Tensor,
    check_device: bool = True,
    check_dtype: bool = True,
    check_layout: bool = True,
    check_stride: bool = False,
) -> None:
    """Checks if the attributes of two tensors match.
    Always checks
    - the :attr:`~torch.Tensor.shape`,
    - whether both inputs are quantized or not,
    - and if they use the same quantization scheme.
    Checks for
    - :attr:`~torch.Tensor.layout`,
    - :meth:`~torch.Tensor.stride`,
    - :attr:`~torch.Tensor.device`, and
    - :attr:`~torch.Tensor.dtype`
    are optional and can be disabled through the corresponding ``check_*`` flag during construction of the pair.
    """

    def raise_mismatch_error(attribute_name: str, actual_value, expected_value):
        raise AssertionError(f"The values for attribute '{attribute_name}' do not match: {actual_value} != {expected_value}.")

    if actual.shape != expected.shape:
        raise_mismatch_error("shape", actual.shape, expected.shape)
    if actual.is_quantized != expected.is_quantized:
        raise_mismatch_error("is_quantized", actual.is_quantized, expected.is_quantized)
    elif actual.is_quantized and actual.qscheme() != expected.qscheme():
        raise_mismatch_error("qscheme()", actual.qscheme(), expected.qscheme())
    if actual.layout != expected.layout:
        if check_layout:
            raise_mismatch_error("layout", actual.layout, expected.layout)
    elif actual.layout == torch.strided and check_stride and actual.stride() != expected.stride():
        raise_mismatch_error("stride()", actual.stride(), expected.stride())
    if check_device and actual.device != expected.device:
        raise_mismatch_error("device", actual.device, expected.device)
    if check_dtype and actual.dtype != expected.dtype:
        raise_mismatch_error("dtype", actual.dtype, expected.dtype)


def _equalize_attributes(actual: torch.Tensor, expected: torch.Tensor) -> tuple[torch.Tensor, torch.Tensor]:
    """Equalizes some attributes of two tensors for value comparison.
    If ``actual`` and ``expected`` are ...
    - ... not on the same :attr:`~torch.Tensor.device`, they are moved CPU memory.
    - ... not of the same ``dtype``, they are promoted  to a common ``dtype`` (according to
        :func:`torch.promote_types`).
    - ... not of the same ``layout``, they are converted to strided tensors.
    Args:
        actual (Tensor): Actual tensor.
        expected (Tensor): Expected tensor.
    Returns:
        (tuple[Tensor, Tensor]): Equalized tensors.
    """
    # The comparison logic uses operators currently not supported by the MPS backends.
    #  See https://github.com/pytorch/pytorch/issues/77144 for details.
    # TODO: Remove this conversion as soon as all operations are supported natively by the MPS backend
    if actual.is_mps or expected.is_mps:  # type: ignore[attr-defined]
        actual = actual.cpu()
        expected = expected.cpu()
    if actual.device != expected.device:
        actual = actual.cpu()
        expected = expected.cpu()
    if actual.dtype != expected.dtype:
        actual_dtype = actual.dtype
        expected_dtype = expected.dtype
        # For uint64, this is not sound in general, which is why promote_types doesn't
        # allow it, but for easy testing, we're unlikely to get confused
        # by large uint64 overflowing into negative int64
        if actual_dtype in [torch.uint64, torch.uint32, torch.uint16]:
            actual_dtype = torch.int64
        if expected_dtype in [torch.uint64, torch.uint32, torch.uint16]:
            expected_dtype = torch.int64
        dtype = torch.promote_types(actual_dtype, expected_dtype)
        actual = actual.to(dtype)
        expected = expected.to(dtype)
    if actual.layout != expected.layout:
        # These checks are needed, since Tensor.to_dense() fails on tensors that are already strided
        actual = actual.to_dense() if actual.layout != torch.strided else actual
        expected = expected.to_dense() if expected.layout != torch.strided else expected
    return actual, expected


def torch_assert_close(
    tensor_a,
    tensor_b,
    rtol=1e-2,
    atol=1e-3,
    max_mismatched_ratio=0.001,
    verbose: bool = False,
    equal_nan: bool = True,
    check_device: bool = True,
    check_dtype: bool = True,
    check_layout: bool = True,
    check_stride: bool = False,
    base_name: str = "LHS",
    ref_name: str = "RHS",
):
    """
    Custom function to assert that two tensors are "close enough," allowing a specified
    percentage of mismatched elements.

    Parameters:
    ----------
    tensor_a : torch.Tensor
        The first tensor to compare.
    tensor_b : torch.Tensor
        The second tensor to compare.
    rtol : float, optional
        Relative tolerance for comparison. Default is 1e-2.
    atol : float, optional
        Absolute tolerance for comparison. Default is 1e-3.
    max_mismatched_ratio : float, optional
        Maximum ratio of mismatched elements allowed (relative to the total number of elements).
        Default is 0.001 (0.1% of total elements).

    Raises:
    -------
    AssertionError:
        If the ratio of mismatched elements exceeds `max_mismatched_ratio`.
    """

    _compare_attributes(
        tensor_a, tensor_b, check_device=check_device, check_dtype=check_dtype, check_layout=check_layout, check_stride=check_stride
    )
    tensor_a, tensor_b = _equalize_attributes(tensor_a, tensor_b)

    mismatched = ~torch.isclose(tensor_a, tensor_b, rtol=rtol, atol=atol, equal_nan=equal_nan)
    # Compute the absolute difference between the two tensors
    diff = torch.abs(tensor_a - tensor_b)
    # Count the number of mismatched elements
    num_mismatched = mismatched.sum().item()

    # Calculate the total number of elements in the tensor
    total_elements = tensor_a.numel()

    # Compute the allowed mismatched elements based on the ratio
    max_allowed_mismatched = int(total_elements * max_mismatched_ratio)

    # Print debug information about the mismatch
    if verbose:
        print(f"Number of mismatched elements: {num_mismatched} / {total_elements} (allowed: {max_allowed_mismatched})")

    # If there are mismatched elements, print the first mismatch
    if num_mismatched > 0:
        # Find the first mismatch index
        flat_idx = torch.argmax(mismatched.view(-1).int()).item()
        idx = np.unravel_index(flat_idx, tensor_a.shape)
        idx = [int(i) for i in idx]
        a_val = tensor_a.reshape(-1)[flat_idx].item()
        b_val = tensor_b.reshape(-1)[flat_idx].item()
        abs_diff = abs(a_val - b_val)
        rel_diff = abs_diff / (abs(b_val) + 1e-12)
        mismatch_info = (
            f"\nFirst mismatch at index {idx}: lhs={a_val:.6f}, rhs={b_val:.6f}, abs_diff={abs_diff:.6f}, rel_diff={rel_diff:.6f}"
        )
    else:
        mismatch_info = ""

    # Modify the exception information
    if num_mismatched > max_allowed_mismatched:
        raise AssertionError(
            f"Too many mismatched elements: {num_mismatched} > {max_allowed_mismatched} "
            f"({max_mismatched_ratio * 100:.2f}% allowed, but get {num_mismatched / total_elements * 100:.2f}%)."
            f"{mismatch_info}"
            f"\nGreatest absolute difference: {diff.max().item()}, "
            f"Greatest relative difference: {(diff / (torch.abs(tensor_b) + 1e-12)).max().item()}"
            f"\n{base_name}: {tensor_a}"
            f"\n{ref_name}: {tensor_b}"
        )
    else:
        return True

